-- Hand-picked camp spots for autonomous bot camps (Traveler's Tent + campfire).
CREATE TABLE IF NOT EXISTS `ai_playerbot_camp_spot` (
  `id`          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `map`         SMALLINT UNSIGNED NOT NULL,
  `x`           FLOAT NOT NULL,
  `y`           FLOAT NOT NULL,
  `z`           FLOAT NOT NULL,
  `orientation` FLOAT NOT NULL DEFAULT 0,
  `zone_id`     INT UNSIGNED NOT NULL DEFAULT 0,
  `name`        VARCHAR(100) NOT NULL DEFAULT '',
  `note`        VARCHAR(255) NOT NULL DEFAULT '',
  `source`      TINYINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM `ai_playerbot_camp_spot` WHERE `source` = 0;

